-- kotak langsung (jalan, lantai plaza): grup,cx,cy,cz,sx,sy,sz,warna[,quat]
local WORLD = "10,0,235,-23000,45000,40,5000,109;11,0,235,-15000,22000,40,4000,57;12,0,235,17000,22000,40,4000,57;13,0,235,1000,22000,40,4000,57;14,0,220,-1000,10000,40,56000,109;22,0,100,-3000,56000,200,62000,110"

local GROUND = "0,-280,0,500000,1000,500000,45"


local function split(s, sep)
	local t = {}
	for piece in string.gmatch(s, "[^" .. sep .. "]+") do table.insert(t, piece) end
	return t
end

local function parseBox(str, skip)
	local f = split(str, ",")
	local o = skip or 0
	local box = {
		cx = tonumber(f[o + 1]) / 1000, cy = tonumber(f[o + 2]) / 1000, cz = tonumber(f[o + 3]) / 1000,
		sx = tonumber(f[o + 4]) / 1000, sy = tonumber(f[o + 5]) / 1000, sz = tonumber(f[o + 6]) / 1000,
		c = tonumber(f[o + 7]),
	}
	if f[o + 8] then
		box.q = {tonumber(f[o + 8]) / 10000, tonumber(f[o + 9]) / 10000, tonumber(f[o + 10]) / 10000, tonumber(f[o + 11]) / 10000}
	end
	return box
end

local old = workspace:FindFirstChild("MapToko")
if old then old:Destroy() end
local root = Instance.new("Model")
root.Name = "MapToko"
root.Parent = workspace

local groupModels = {}
local function groupModel(g)
	if not groupModels[g] then
		local m = Instance.new("Model")
		m.Name = GROUPS[g] or ("Grup" .. g)
		m.Parent = root
		groupModels[g] = m
	end
	return groupModels[g]
end

local colorCache = {}
local function colorOf(ci, variant)
	local col = PALETTE[ci] or {128, 128, 128, 0, 0}
	local key = ci * 10 + variant
	local c = colorCache[key]
	if not c then
		c = Color3.fromRGB(col[1], col[2], col[3])
		if variant > 0 and col[5] == 1 and SHOP_HUE[variant] and SHOP_HUE[variant] ~= 0 then
			local h, s, v = c:ToHSV()
			c = Color3.fromHSV((h + SHOP_HUE[variant]) % 1, s, v)
		end
		colorCache[key] = c
	end
	return c, col[4] == 1
end

local count = 0
local function makePart(parent, cf, size, ci, variant)
	local color, neon = colorOf(ci, variant or 0)
	local p = Instance.new("Part")
	p.Anchored = true
	p.Size = size
	p.CFrame = cf
	p.Color = color
	p.Material = neon and Enum.Material.Neon or MATERIAL
	p.TopSurface = Enum.SurfaceType.Smooth
	p.BottomSurface = Enum.SurfaceType.Smooth
	p.Parent = parent
	count += 1
	if count % 250 == 0 then task.wait() end
end

local function boxCF(box, k)
	local cf = CFrame.new(box.cx * k, box.cy * k, box.cz * k)
	if box.q then cf = cf * CFrame.new(0, 0, 0, box.q[1], box.q[2], box.q[3], box.q[4]) end
	return cf
end

local parsedTemplates = {}
for mi, str in pairs(TEMPLATES) do
	local list = {}
	for _, bs in ipairs(split(str, ";")) do table.insert(list, parseBox(bs, 0)) end
	parsedTemplates[mi] = list
end

-- 1) tanah hijau
if BUILD_GROUND and GROUND ~= "" then
	local b = parseBox(GROUND, 0)
	local m = Instance.new("Model")
	m.Name = "Tanah"
	m.Parent = root
	local p = Instance.new("Part")
	p.Name = "TanahHijau"
	p.Anchored = true
	p.Size = Vector3.new(b.sx * SCALE, b.sy * SCALE, b.sz * SCALE)
	p.CFrame = CFrame.new(ORIGIN) * boxCF(b, SCALE)
	p.Color = GROUND_COLOR
	p.Material = Enum.Material.Grass
	p.Parent = m
end

-- 2) objek berinstance (toko, plot, pohon, lampu, tembok, air mancur, semak)
for _, row in ipairs(split(INSTANCES, ";")) do
	local f = split(row, ",")
	local g, mi = tonumber(f[1]), tonumber(f[2])
	local pos = Vector3.new(tonumber(f[3]), tonumber(f[4]), tonumber(f[5])) / 1000 * SCALE + ORIGIN
	local qx, qy, qz, qw = tonumber(f[6]) / 10000, tonumber(f[7]) / 10000, tonumber(f[8]) / 10000, tonumber(f[9]) / 10000
	local s = tonumber(f[10]) / 1000
	local variant = tonumber(f[11]) or 0
	local instCF = CFrame.new(pos.X, pos.Y, pos.Z, qx, qy, qz, qw)
	local k = s * SCALE
	local parent = groupModel(g)
	for _, b in ipairs(parsedTemplates[mi]) do
		if math.max(b.sx, b.sy, b.sz) * s >= MIN_SIZE then
			makePart(parent, instCF * boxCF(b, k), Vector3.new(b.sx * k, b.sy * k, b.sz * k), b.c, variant)
		end
	end
end

-- 3) jalan & lantai plaza
for _, row in ipairs(split(WORLD, ";")) do
	local g = tonumber(string.match(row, "^(%d+),"))
	local b = parseBox(row, 1)
	makePart(groupModel(g), CFrame.new(ORIGIN) * boxCF(b, SCALE), Vector3.new(b.sx * SCALE, b.sy * SCALE, b.sz * SCALE), b.c, 0)
end

print(("[MapToko] selesai: %d part"):format(count))
